export default function telegramChat({ body }) {
  const chatId = body?.message?.chat?.id;
  if (!Number.isSafeInteger(chatId) || chatId === 0) throw new Error('Telegram update has no valid message chat ID');
  return { chatId: String(chatId) };
}

