export default function weatherReply({ weather }) {
  const description = weather.weather?.[0]?.description;
  const temperature = weather.main?.temp, feelsLike = weather.main?.feels_like;
  if (typeof description !== 'string' || !description || !Number.isFinite(temperature) || !Number.isFinite(feelsLike)) throw new Error('OpenWeather returned incomplete current-weather data');
  const escaped = description.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const text = `Right now, we have ${escaped}. The temperature is ${temperature}°C but it really feels like ${feelsLike}°C 🙂`;
  if (text.length > 4096) throw new Error('The weather reply exceeds Telegram’s message limit');
  return { text };
}
